use std::fs

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let lim = 200001
    let mut comp: Vec<bool> = []
    let mut cnt: Vec<int> = []
    let mut last: Vec<int> = []
    for i in 0..lim {
        comp.push(false)
        cnt.push(0)
        last.push(0)
    }
    let mut i = 2
    while i * i < lim {
        if !comp[i] {
            let mut j = i * i
            while j < lim {
                comp[j] = true
                j += i
            }
        }
        i += 1
    }
    let mut c = 0
    let mut l = 0
    for k in 0..lim {
        if k >= 2 && !comp[k] {
            c += 1
            l = k as int
        }
        cnt[k] = c
        last[k] = l
    }
    let mut first = true
    for line in text.lines() {
        let t = line.trim()
        if t.len() == 0 { continue }
        if first {
            first = false
            continue
        }
        let n: int = t.parse().unwrap_or(0)
        if n < 2 {
            println("0 none")
        } else {
            println("${cnt[n]} ${last[n]}")
        }
    }
}

